with metrics as (select *, last_value(quantity) ignore nulls over w_running as last_known_quantity, sum(quantity) over (partition by store_id, product_id order by quantity, id rows between unbounded preceding and current row) as running_quantity, lag(quantity, 2) over w_ordered as prev_quantity, sum(quantity) over (partition by store_id order by quantity, id rows between unbounded preceding and current row) as cumulative_quantity from inventory window w_running as (partition by product_id order by last_restock, id rows between unbounded preceding and current row), w_ordered as (partition by date_trunc('month', last_restock), product_id order by quantity, id)) select s.id, s.store_id, s.product_id, s.quantity, s.last_restock, s.last_known_quantity, s.running_quantity, s.prev_quantity, s.cumulative_quantity, (select sum(t2.unit_price) from order_items t2 where t2.product_id = s.product_id) as sum_order_item_unit_price from metrics s order by prev_quantity desc, store_id;
